import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String TARTIB = "RWXD";
        int n = Integer.parseInt(in.next());
        for (int i = 0; i < n; i++) {
            String name = in.next();
            String share = in.next();
            String ntfs = in.next();
            StringBuilder eff = new StringBuilder();
            for (char c : TARTIB.toCharArray()) {
                if (share.indexOf(c) >= 0 && ntfs.indexOf(c) >= 0) {
                    eff.append(c);
                }
            }
            System.out.println(name + ": " + (eff.length() > 0 ? eff : "-"));
        }
    }
}

solution.cpp:
#include <iostream>
#include <string>
using namespace std;

int main() {
    string TARTIB = "RWXD";
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        string name, share, ntfs;
        cin >> name >> share >> ntfs;
        string eff;
        for (char c : TARTIB) {
            if (share.find(c) != string::npos && ntfs.find(c) != string::npos) {
                eff += c;
            }
        }
        cout << name << ": " << (eff.empty() ? "-" : eff) << endl;
    }
    return 0;
}
